 export const TASA_IVA = 0.13;

+// Tasa de IVA configurable por entorno: TASA_IVA (número entre 0 y 1). Sin definir → 0.13; inválida → error.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined) return TASA_IVA;
+  const texto = String(crudo).trim();
+  const tasa = Number(texto);
+  if (texto === "" || !Number.isFinite(tasa) || tasa < 0 || tasa > 1)
+    throw new RangeError(`TASA_IVA inválida: debe ser un número entre 0 y 1 (recibido: "${crudo}")`);
+  return tasa;
+}
+
 // RF-001: el NIT del cliente es numérico, de 5 a 12 dígitos.
 export function validarNit(nit) {
   return typeof nit === "string" && /^\d{5,12}$/.test(nit);
